//! Differential test against the lxml oracle (`fixtures/lxml_stream.json`, generated by
//! `fixtures/gen_lxml_stream.py` from the original XMLDeclStrip + XMLPullParser pipeline).
//!
//! Inputs: every CoT connection of the an01 vectors (`shared/spec/vectors/cot`) plus hand-written
//! edge cases. Compared per chunk: emitted events (structure: tag, attrs, text, tail, children)
//! and the chunk on which the stream fails.
#![allow(clippy::unwrap_used)] // test helpers outside #[test] fns

mod common;

use std::collections::BTreeMap;

use common::{b64, run};
use serde_json::Value;

/// Accepted divergences (ADR-002 / cot-server.md §5; reported in the S-303 handoff).
/// id → reason. Everything not listed must match lxml exactly.
const DIVERGENCES: &[(&str, &str)] = &[
    (
        "quirk_unknown_entity_restart",
        "libxml2 drops the rest of the chunk and restarts as a bare document (next-but-one \
         top-level element => disconnect); ADR-002: drop the event, continue",
    ),
    (
        "quirk_bare_amp_zombie",
        "libxml2 silently stops parsing for good; Rust: fatal error",
    ),
    (
        "quirk_unterminated_charref",
        "libxml2 silently stops parsing for good; Rust: fatal error",
    ),
];

/// Accepted divergences of `parse_element` vs `etree.fromstring`.
const DOC_DIVERGENCES: &[(&str, &str)] = &[("doctype", "DTD is rejected (ADR-002, D-1)")];

fn fixture() -> Value {
    let p = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/lxml_stream.json"
    );
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

/// `TAKY_XML_ORACLE=<file.json>` runs [`matches_lxml_oracle`] on another oracle file of the
/// same format (e.g. a large random differential set generated outside the repo).
fn oracle() -> (Value, bool) {
    match std::env::var("TAKY_XML_ORACLE") {
        Ok(p) => (
            serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap(),
            true,
        ),
        Err(_) => (fixture(), false),
    }
}

fn chunks(item: &Value) -> Vec<Vec<u8>> {
    item["chunks_b64"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| b64(c.as_str().unwrap()))
        .collect()
}

#[test]
fn matches_lxml_oracle() {
    let (fx, external) = oracle();
    let mut failures = Vec::new();
    let mut checked = 0;
    for item in fx["items"].as_array().unwrap() {
        let id = item["id"].as_str().unwrap();
        if DIVERGENCES.iter().any(|(d, _)| *d == id) {
            continue;
        }
        let got = run(&chunks(item));
        let want_err = item["error_at"].as_u64().map(|v| v as usize);
        let want_events: Vec<Vec<Value>> = serde_json::from_value(item["events"].clone()).unwrap();
        checked += 1;
        if got.error_at != want_err || got.events != want_events {
            failures.push(format!(
                "{id}: lxml error_at={want_err:?} events={}\n      rust error_at={:?} ({:?}) events={}",
                serde_json::to_string(&want_events).unwrap(),
                got.error_at,
                got.error,
                serde_json::to_string(&got.events).unwrap()
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(external || checked > 100, "only {checked} items checked");
    eprintln!("lxml oracle: {checked} items match");
}

#[test]
fn documents_match_fromstring() {
    let fx = fixture();
    let docs = fx["documents"].as_array().unwrap();
    let mut failures = Vec::new();
    for d in docs {
        let id = d["id"].as_str().unwrap();
        if DOC_DIVERGENCES.iter().any(|(x, _)| *x == id) {
            continue;
        }
        let input = b64(d["input_b64"].as_str().unwrap());
        let got = taky_xml::parse_element(&input, &taky_xml::Limits::DEFAULT);
        let ok = match (&got, &d["ok"]) {
            (Ok(e), want) if !want.is_null() => common::dump(e) == *want,
            (Err(_), want) => want.is_null(),
            _ => false,
        };
        if !ok {
            failures.push(format!("{id}: lxml {} / rust {got:?}", d["ok"]));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
    assert!(docs.len() >= 15);
}

/// The fixture's vector inputs must be the current vectors (read via `taky_common::vectors`).
#[test]
fn fixture_matches_current_vectors() {
    let dir = taky_common::vectors::vectors_dir().join("cot");
    let mut sessions: BTreeMap<String, Vec<Vec<u8>>> = BTreeMap::new();
    let mut files: Vec<_> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    files.sort();
    for path in files {
        if path.extension().and_then(|e| e.to_str()) != Some("json") {
            continue;
        }
        let v: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
        let vid = v["id"].as_str().unwrap();
        let mut n: BTreeMap<String, u32> = BTreeMap::new();
        let mut cur: BTreeMap<String, String> = BTreeMap::new();
        for st in v["steps"].as_array().unwrap() {
            let client = st["client"].as_str().unwrap_or_default().to_owned();
            match st["op"].as_str().unwrap() {
                "connect" => {
                    let k = n.entry(client.clone()).or_default();
                    *k += 1;
                    cur.insert(client.clone(), format!("{vid}/{client}#{k}"));
                }
                "send" => {
                    let key = cur[&client].clone();
                    let cs: Vec<Vec<u8>> = if let Some(b) = st.get("chunks_b64") {
                        b.as_array()
                            .unwrap()
                            .iter()
                            .map(|c| b64(c.as_str().unwrap()))
                            .collect()
                    } else {
                        st["chunks"]
                            .as_array()
                            .unwrap()
                            .iter()
                            .map(|c| c.as_str().unwrap().as_bytes().to_vec())
                            .collect()
                    };
                    sessions.entry(key).or_default().extend(cs);
                }
                _ => {}
            }
        }
    }
    let fx = fixture();
    let fixture_sessions: BTreeMap<String, Vec<Vec<u8>>> = fx["items"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|i| i["source"] == "vector")
        .map(|i| (i["id"].as_str().unwrap().to_owned(), chunks(i)))
        .collect();
    assert_eq!(
        sessions.keys().collect::<Vec<_>>(),
        fixture_sessions.keys().collect::<Vec<_>>(),
        "vector set changed: regenerate tests/fixtures/lxml_stream.json"
    );
    for (k, v) in &sessions {
        assert_eq!(
            v, &fixture_sessions[k],
            "{k}: chunks changed: regenerate the fixture"
        );
    }
}
